PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?zaal ?naam WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:heeftBeschikbaarheid ?beschikbaarheid .

  ?beschikbaarheid zaalreservatie:tijdsslot ?tijdsslot .
  ?tijdsslot zaalreservatie:dagVanWeek zaalreservatie:Vrijdag ;
             zaalreservatie:startTijd ?start .

  FILTER(HOURS(?start) >= 18)
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?zaal ?naam ?capaciteit WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:capaciteit ?capaciteit ;
        zaalreservatie:heeftVoorziening ?beamer ;
        zaalreservatie:heeftVoorziening ?toegankelijkheid .

  ?beamer a zaalreservatie:Voorziening .
  {
    ?beamer zaalreservatie:voorziening_type ?beamerType .
    FILTER(REGEX(?beamerType, "beamer|projector|projektor", "i"))
  } UNION {
    ?beamer rdfs:label ?beamerLabel .
    FILTER(REGEX(?beamerLabel, "beamer|projector|projektor", "i"))
  }

  ?toegankelijkheid a zaalreservatie:Voorziening .
  {
    ?toegankelijkheid zaalreservatie:toegankelijk zaalreservatie:Rolstoeltoegankelijk .
  } UNION {
    ?toegankelijkheid zaalreservatie:voorziening_type ?toegankelijkheidType .
    FILTER(REGEX(?toegankelijkheidType, "rolstoel|wheelchair", "i"))
  } UNION {
    ?toegankelijkheid rdfs:label ?toegankelijkheidLabel .
    FILTER(REGEX(?toegankelijkheidLabel, "rolstoel|wheelchair", "i"))
  }

  FILTER(?capaciteit >= 80)
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?zaal ?naam WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:heeftBeschikbaarheid ?beschikbaarheid .

  ?beschikbaarheid zaalreservatie:tijdsslot ?tijdsslot .
  ?tijdsslot zaalreservatie:startTijd ?start ;
             zaalreservatie:eindTijd ?eind .

  BIND(NOW() + "P1D"^^xsd:duration AS ?morgen)
  BIND(xsd:dateTime(CONCAT(SUBSTR(STR(?morgen), 1, 10), "T14:00:00")) AS ?gewensteStart)
  BIND(xsd:dateTime(CONCAT(SUBSTR(STR(?morgen), 1, 10), "T18:00:00")) AS ?gewensteEind)

  FILTER(?start <= ?gewensteStart && ?eind >= ?gewensteEind)
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX locn: <http://www.w3.org/ns/locn#>

SELECT ?zaal ?naam ?prijs WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:locatie ?locatie ;
        zaalreservatie:heeftPrijsinformatie ?prijsinfo ;
        zaalreservatie:heeftBeschikbaarheid ?beschikbaarheid .

  ?locatie locn:postNaam "Leuven" .

  ?prijsinfo zaalreservatie:bedrag ?prijs .

  FILTER(?prijs < 200)
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?zaal ?naam WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:heeftVoorziening ?keuken ;
        zaalreservatie:heeftBeschikbaarheid ?beschikbaarheid .

  ?keuken a zaalreservatie:Voorziening .
  {
    ?keuken zaalreservatie:voorziening_type ?keukenType .
    FILTER(REGEX(?keukenType, "keuken|kitchen|kitchenette", "i"))
  } UNION {
    ?keuken rdfs:label ?keukenLabel .
    FILTER(REGEX(?keukenLabel, "keuken|kitchen|kitchenette", "i"))
  }

  ?beschikbaarheid zaalreservatie:tijdsslot ?tijdsslot .
  ?tijdsslot zaalreservatie:startTijd ?start ;
             zaalreservatie:eindTijd ?eind .

  BIND(NOW() AS ?nu)

  FILTER(?start <= ?nu && ?eind >= ?nu)

  FILTER NOT EXISTS {
    ?reservatie a zaalreservatie:Reservatie ;
                zaalreservatie:reserveertZaal ?zaal ;
                zaalreservatie:tijdsslot ?resSlot .
    ?resSlot zaalreservatie:startTijd ?resStart ;
             zaalreservatie:eindTijd ?resEind .
    FILTER(?resStart <= ?nu && ?resEind >= ?nu)
  }
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX locn: <http://www.w3.org/ns/locn#>

SELECT ?naam ?capaciteit ?stad WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:capaciteit ?capaciteit ;
        zaalreservatie:locatie ?locatie .

  OPTIONAL {
    ?locatie locn:postNaam ?stad .
  }
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?voorziening ?type ?label WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam "Vergaderzaal A" ;
        zaalreservatie:heeftVoorziening ?voorziening .

  OPTIONAL { ?voorziening zaalreservatie:voorziening_type ?type . }
  OPTIONAL { ?voorziening rdfs:label ?label . }
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>

SELECT ?zaal ?naam ?capaciteit WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:capaciteit ?capaciteit .

  FILTER(?capaciteit > 100)
}
ORDER BY DESC(?capaciteit)

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?reservatie ?zaal ?zaalNaam ?start ?eind WHERE {
  ?reservatie a zaalreservatie:Reservatie ;
              zaalreservatie:reserveertZaal ?zaal ;
              zaalreservatie:tijdsslot ?tijdsslot .

  ?zaal zaalreservatie:naam ?zaalNaam .

  ?tijdsslot zaalreservatie:startTijd ?start ;
             zaalreservatie:eindTijd ?eind .

  BIND(NOW() AS ?nu)
  BIND(?nu + "P7D"^^xsd:duration AS ?volgendeWeekStart)
  BIND(?nu + "P14D"^^xsd:duration AS ?volgendeWeekEind)

  FILTER(?start >= ?volgendeWeekStart && ?start < ?volgendeWeekEind)
}
ORDER BY ?start

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?zaal ?naam WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:naam ?naam ;
        zaalreservatie:heeftVoorziening ?wifi ;
        zaalreservatie:locatie ?locatie .

  ?wifi a zaalreservatie:Voorziening .
  {
    ?wifi zaalreservatie:voorziening_type ?wifiType .
    FILTER(REGEX(?wifiType, "wifi|wi-fi|wireless|internet", "i"))
  } UNION {
    ?wifi rdfs:label ?wifiLabel .
    FILTER(REGEX(?wifiLabel, "wifi|wi-fi|wireless|internet", "i"))
  }

  ?locatie zaalreservatie:toegankelijkheidOpenbaarVervoer true .
}

PREFIX zaalreservatie: <https://data.vlaanderen.be/ns/zaalreservatie#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  ?zaal a zaalreservatie:Zaal ;
        zaalreservatie:heeftVoorziening ?projector .

  ?projector a zaalreservatie:Voorziening .
